// SyncSection.tsx — the account's deploy key, which is what lets a repository be cloned and
// pushed at all. Generated by pl8, because that service holds the repositories; the engine's
// machine fetches a copy when it has to clone. It is an ACCOUNT fact, not a desktop one, which
// is why this section is the one the hosted studio still draws.
// See packages/git-repos/docs/keys.md and apps/studio-desktop/docs/settings.md.

import { useEffect, useState } from "react";
import { projects } from "../projects/api";
import { Action, Row, Section } from "./Section";

export function SyncSection() {
  const [key, setKey] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    void projects
      .sshKey()
      .then((r) => setKey(r.publicKey))
      .catch((e: Error) => setError(e.message));
  }, []);

  const generate = () => {
    setBusy(true);
    setError(null);
    void projects
      .generateSshKey()
      .then((r) => setKey(r.publicKey))
      .catch((e: Error) => setError(e.message))
      .finally(() => setBusy(false));
  };

  const copy = () => {
    if (!key) return;
    void navigator.clipboard.writeText(key).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  };

  return (
    <Section
      title="Deploy key"
      hint="Add this public key at your git host — as a deploy key, or as an account SSH key — before adding a repository. The same key reads the repository here and clones it onto your engine's machine."
    >
      {key ? (
        <>
          <Row
            label="Your key is ready"
            detail="One per account, pasted once at the host."
          >
            <Action onClick={copy}>{copied ? "Copied" : "Copy"}</Action>
          </Row>
          {/* Outside the row: a Row truncates its label, and a key you can only see the start of is one you cannot check. */}
          <div className="px-4 py-2.5">
            <code className="block overflow-x-auto whitespace-pre rounded bg-neutral-950 px-2 py-1.5 font-mono text-neutral-400 text-xs">
              {key}
            </code>
          </div>
        </>
      ) : (
        <Row
          label="No key yet"
          detail="Nothing can be cloned until there is one."
        >
          <Action onClick={generate} disabled={busy}>
            {busy ? "Generating…" : "Generate"}
          </Action>
        </Row>
      )}
      {error && <Row label={`⚠ ${error}`} />}
    </Section>
  );
}
